'use strict';
/* public/js/84-coop.js -- levels, team quota, heavy loot, dropped sacks, helping friends, pings/chat, flashlight, co-op tick. Generated by scripts/split-client.mjs; see ARCHITECTURE.md. */
/* ---- levels: XP stays with your name in this browser (and on the server) ---- */
const PROG={xp:0,sent:0};
const xpNeed=l=>60+l*40;
function levelOf(xp){let l=1;while(l<20&&xp>=xpNeed(l)){xp-=xpNeed(l);l++}return{l,into:xp,need:xpNeed(l)}}
function myLevel(){return levelOf(PROG.xp).l}
const PERKS=[[2,'digging 10% faster'],[3,'a straw hat'],[4,'+20 water'],[5,'one more sack slot'],[6,'a black hat'],[8,'Lucky Eye: dust puffs up over buried loot near you'],[10,'a gold hat'],[12,'crawling faster when downed'],[15,'a piggy for your head'],[16,'one more sack slot']];
function loadProg(){try{PROG.xp=num(JSON.parse(localStorage.getItem('cgl-prog-'+S.name.toLowerCase())||'{}').xp,0,1e8,0)|0}catch(e){}}
function saveProg(){try{localStorage.setItem('cgl-prog-'+S.name.toLowerCase(),JSON.stringify({xp:PROG.xp}))}catch(e){}}
function myTag(){return`${S.name} (you) · LV ${myLevel()}`}
function addXP(n){
  if(!S.started||!(n>0))return;const before=myLevel();PROG.xp+=n;saveProg();const l=myLevel();
  if(l>before){sfx.gold();const perk=PERKS.filter(p=>p[0]>before&&p[0]<=l).map(p=>p[1]).join(', ');toast(`LEVEL ${l}!`+(perk?` You unlocked ${perk}.`:''),'gold',5500);setHat(me,l);meL.n.textContent=myTag()}
}
setInterval(()=>{if(online()&&PROG.xp!==PROG.sent){PROG.sent=PROG.xp;wsSend({t:'xp',xp:PROG.xp})}},5000);
function sackMax(){const l=myLevel();return 6+(S.up.bigsack?3:0)+(l>=5?1:0)+(l>=16?1:0)}
const hatTier=l=>l>=15?4:l>=10?3:l>=6?2:l>=3?1:0;
function setHat(p,l){
  const t=hatTier(l);if(!p||!p.hat||p.hatT===t)return;p.hatT=t;if(p.model){modelHat(p,t);return}if(!t)return;const h=p.hat;while(h.children.length)h.remove(h.children[0]);
  if(t===4){const b=box(0.3,0.22,0.42,0xf2a0b0);b.position.y=0.12;const hd=box(0.2,0.18,0.14,0xf2a0b0);hd.position.set(0,0.16,0.26);const sn=box(0.09,0.06,0.04,0xd97a8e);sn.position.set(0,0.14,0.34);h.add(b,hd,sn);return}
  const c=[0,0xd9c27a,0x222222,0xd4af37][t];const br=cyl(0.42,0.42,0.04,10,c),cr=cyl(0.2,0.24,0.2,8,c);cr.position.y=0.12;h.add(br,cr);
}

/* ---- the crew bank (the gold rush, 2026-09-30): since 2026-10-01 the crew wallet (84-wallet.js): all the gold anyone has, shared by
   the whole crew for the big purchases. There's no quota any more and nobody gets fired: curfew just ends the day. ---- */
const RUN={day:1,bank:0,quota:SIM.quotaFor(1,1),curse:0,mood:'normal'};   // quota: the Warden's, out of the bank at curfew   // curse/mood: 81-mood.js
function loadRun(){try{const o=JSON.parse(sessionStorage.getItem('cgl-run')||'null');if(o){RUN.day=num(o.day,1,999,1)|0;RUN.bank=num(o.bank,0,1e9,0)|0;RUN.curse=num(o.curse,0,100,0);RUN.mood=SIM.MOODS[o.mood]?o.mood:'normal'}}catch(e){}RUN.quota=SIM.quotaFor(RUN.day,1);$('#dayTag').textContent='Day '+RUN.day}
function saveRun(){if(!online())try{sessionStorage.setItem('cgl-run',JSON.stringify({day:RUN.day,bank:RUN.bank,curse:RUN.curse,mood:RUN.mood}))}catch(e){}}
function deposited(m){const v=num(m.v,0,1e6,0)|0;if(m.pipe){toast(`${m.id===myId()?'Your':(m.n||'A camper')+'\'s'} sand came through the pipeline: the sifter puts ${v} gold in the crew bank.`,'gold',3600);return}if(m.bot)toast(`${String(m.bot).slice(0,16)} sifted ${v} gold into the crew bank.`,'',3200);else if(m.id!==myId())toast(`${m.n||'A camper'} put ${v} gold in the crew bank.`,'gold',3200)}
function setRun(m){
  RUN.day=num(m.day,1,999,1)|0;noteDay(RUN.day);RUN.bank=num(m.bank,0,1e9,0)|0;RUN.quota=num(m.quota,1,1e9,SIM.quotaFor(RUN.day,1))|0;if(m.mood!=null&&SIM.MOODS[m.mood])RUN.mood=m.mood;if(m.curse!=null)RUN.curse=num(m.curse,0,100,0);moodHud();
}
function newDay(m){m=m||{};{const fl=foundLine(m.found);if(fl)setTimeout(()=>toast(fl,'gold',6000),600)}FOUND.mine=0;toast(m.grace?`Day ${RUN.day}. You only just got here, so the Warden let the quota slide. Today she wants ${RUN.quota} gold in the crew bank by curfew.`:`Day ${RUN.day}. The Warden took her ${m.paid||''} gold. Today she wants ${RUN.quota} in the crew bank by curfew.`,'gold',7000);addXP(50)}
/* short at curfew: the whole crew's fired. Everything starts over from nothing; your level stays. (The crew wallet, S.seeds,
   is the server's: it starts the new run at 0, so it isn't wiped here.) */
function fired(bank,quota){
  if(!$('#fired').hidden)return;
  $('#firedText').textContent=`The crew bank had ${bank} of the ${quota} gold the Warden wanted.`+(foundLine(RUN.lastFound)?' '+foundLine(RUN.lastFound)+'.':'');$('#fired').hidden=false;releaseLock();zeroniSting(0.8);
  Object.assign(S,{bucket:0,hopper:0,pipe:0,dynamite:0,pan:0,sack:[],up:{},onions:1,batt:100,hasKB:false,reported:false,holesDone:0,carry:null});saveSession();
}
$('#firedBtn').onclick=()=>{saveSession();try{sessionStorage.removeItem('cgl-run');localStorage.removeItem('cgl-crew')}catch(e){}location.reload()};
function soloEndOfDay(){
  if(online()||!S.started)return;
  const played=S.dayPlay||0;S.dayPlay=0;const q=RUN.quota;
  if(RUN.bank<q&&played>=180){RUN.lastFound=RUN.found||{};RUN.found={};const b=RUN.bank;RUN.day=1;RUN.bank=0;RUN.quota=SIM.quotaFor(1,1);saveRun();fired(b,q);return}
  const found=RUN.found||{};RUN.found={};RUN.lastFound=found;
  const paid=RUN.bank>=q;if(paid)RUN.bank-=q;RUN.day++;noteDay(RUN.day);RUN.quota=SIM.quotaFor(RUN.day,1);RUN.mood=SIM.rollMood(RUN.day,RUN.curse);S.refills=0;saveRun();$('#dayTag').textContent='Day '+RUN.day;newDay(paid?{paid:q,found}:{grace:true,found});
}

/* ---- heavy loot: too big for the sack. Grab it (hold R, 84-grab.js) and get it to the Supply Depot window (sim.js SELL); the safe takes two to lift ---- */
const PROPS=new Map();
function propMesh(type){
  const g=new T.Group();
  if(ITEM_MODELS[type]){g.add(itemMesh(type));scene.add(g);return g}
  if(type==='cart'){   // the crew's wheelbarrow (84-grab.js): tray, wheel up front, two handles
    const tray=box(0.75,0.28,1.0,0x6f7f6a);tray.position.set(0,0.55,0.05);g.add(tray);
    const lip=box(0.8,0.06,1.05,0x4d5a4a);lip.position.set(0,0.7,0.05);g.add(lip);
    const wheel=cyl(0.24,0.24,0.1,12,0x2a2a2a);wheel.rotation.z=Math.PI/2;wheel.position.set(0,0.24,0.62);g.add(wheel);
    for(const s of[-1,1]){const h=box(0.05,0.05,1.3,0x8a6440);h.position.set(s*0.3,0.55,-0.45);h.rotation.x=0.18;g.add(h);const l=box(0.05,0.4,0.05,0x5a4a3a);l.position.set(s*0.28,0.2,-0.35);g.add(l)}
    scene.add(g);return g}   // the Blender safe / strongbox (23-models.js), once loaded
  if(type==='safe'){const b=box(1.1,1.1,1,0x3b3f45);b.position.y=0.55;const d=cyl(0.18,0.18,0.06,10,0xb8b8b8);d.rotation.x=Math.PI/2;d.position.set(0,0.62,0.52);const h=box(0.3,0.06,0.06,0xd4af37);h.position.set(0.3,0.35,0.52);g.add(b,d,h)}
  else{const b=box(1.2,0.7,0.8,0x5b3a1e);b.position.y=0.35;g.add(b);for(const x of[-0.4,0.4]){const s=box(0.1,0.72,0.82,0xd4af37);s.position.set(x,0.36,0);g.add(s)}}
  scene.add(g);return g;
}
function addProp(id,type,x,z,val,val0){if(PROPS.has(id)||!(type in SIM.HEAVY||type==='cart'))return;const g=propMesh(type);g.position.set(x,groundAt(x,z),z);   // val: a carried find's own worth (45-state.js carryFind); val0: what it was when dug up
  const v=val!=null?val:SIM.HEAVY[type];PROPS.set(id,{id,type,x,z,n:0,g,val:type==='cart'?undefined:v,val0:type==='cart'?undefined:(val0!=null?val0:v),L:makeLabel(g,type==='cart'?'Wheelbarrow':LOOT[type].name+' · '+v+' gold','',type==='cart'?1.2:1.7)})}
function removeProp(id){const pr=PROPS.get(id);if(!pr)return;scene.remove(pr.g);dropLabel(pr.L);PROPS.delete(id);if(S.carry===id)S.carry=null}
function propSold(id,v,who){
  const pr=PROPS.get(id),name=pr?propName(pr):'heavy find';removeProp(id);
  const mine=who.includes(myId());toast(`Mr. Pendanski paid ${v} gold for the ${name}.`+(who.length>1?' Split between everyone who carried it.':''),'good',4500);
  if(mine){S.seeds+=Math.round(v/Math.max(1,who.length));foundGold(Math.round(v/Math.max(1,who.length)));addXP(50);sfx.coin();countUp('hauls',3,'hauler')}
}
function propNear(r){let best=null,bd=r*r;for(const pr of PROPS.values()){const d2=(pr.x-P.x)**2+(pr.z-P.z)**2;if(d2<bd){bd=d2;best=pr}}return best}
function carryN(){const pr=S.carry==null?null:PROPS.get(S.carry);return pr?Math.max(1,pr.n||0):1}

/* ---- dropped sacks: get caught and your sack lands where you fell; anyone can pick it up ---- */
const BAGS=new Map();let bagSeq=1;
function addBag(id,x,z,items,n){
  if(BAGS.has(id))return;const g=new T.Group();const s=cyl(0.22,0.34,0.5,7,0x9b7b4a);s.position.y=0.25;const t=cyl(0.06,0.12,0.14,6,0x7a5f38);t.position.y=0.56;g.add(s,t);
  g.position.set(x,groundAt(x,z),z);scene.add(g);BAGS.set(id,{id,x,z,items,n,g,L:makeLabel(g,(n||'Someone')+'\'s sack','',1)});
}
function removeBag(id){const b=BAGS.get(id);if(!b)return;scene.remove(b.g);dropLabel(b.L);BAGS.delete(id)}
function bagNear(r){let best=null,bd=r*r;for(const b of BAGS.values()){const d2=(b.x-P.x)**2+(b.z-P.z)**2;if(d2<bd){bd=d2;best=b}}return best}
function dropBag(){if(!S.sack.length)return;const items=S.sack.slice(0,12);S.sack=[];if(online())wsSend({t:'bag',x:P.x,z:P.z,items});else addBag(bagSeq++,P.x,P.z,items,S.name)}
function takeBag(items,n){countUp('bags',3,'magnet');const ok=items.filter(t=>LOOT[t]&&!LOOT[t].key&&!LOOT[t].heavy);S.sack.push(...ok);sfx.find();toast(`Picked up ${n===S.name?'your':(n||'a camper')+'\'s'} sack: ${ok.length} item${ok.length===1?'':'s'}.`,'good')}

/* ---- helping each other: pick up downed friends, pull friends out of deep holes ---- */
function remoteNear(test,r){let best=null,bd=r*r;for(const[rid,R]of remotes){if(R.room!==S.tent||!test(R))continue;const g=R.p.g.position,d2=(g.x-P.x)**2+(g.z-P.z)**2;if(d2<bd){bd=d2;best={rid,R}}}return best}
function holeDepthHere(){return Math.max(0,baseH(P.x,P.z)-P.y)}
function isTrapped(){return S.started&&!S.ko&&!inTent()&&!S.inTown&&P.grounded&&holeDepthHere()>1.8&&!inSinkhole()}   // a sinkhole has its own trapped state (87-sinkhole.js): no Space-climb, no rope, only a friend
function popOut(){
  const h=holeNear(P.x,P.z,HOLE_R*1.2);let dx=Math.sin(P.fa),dz=Math.cos(P.fa);
  if(h){const ex=P.x-h.x,ez=P.z-h.z,el=Math.hypot(ex,ez);if(el>0.05){dx=ex/el;dz=ez/el}P.x=h.x+dx*(h.r+0.7);P.z=h.z+dz*(h.r+0.7)}else{P.x+=dx*2;P.z+=dz*2}
  P.y=groundAt(P.x,P.z);P.vy=0;S.climbT=0;sfx.thud();
}
function revived(by){if(!S.ko)return;S.ko=0;setHp(REVIVE_HP);S.stam=S.hp;S.hurtT=0;$('#ko').hidden=true;twSt=0;twStT=0;P.kx=P.kz=0;me.g.rotation.set(0,me.g.rotation.y,0);toast(`${by} picked you up!`,'good',3000);sfx.find()}
function downed(dt){
  // downed with friends around: crawl, and wait for someone to pick you up
  const fine=$('#koFine');
  if(othersOnline()&&stepMyBody(dt)){fine.textContent=S.inCart!=null?'You\'re in the wheelbarrow. Hang on.':'Your crew has hold of you. Get carried inside the fence and you\'re back up.';me.g.position.set(P.x,P.y,P.z);return}
  if(othersOnline()){fine.textContent=`Downed. ${Math.ceil(S.ko)}s left for a friend to pick you up (they hold F next to you). You can crawl.`;
    let ix=(KEYS['d']||KEYS['arrowright']?1:0)-(KEYS['a']||KEYS['arrowleft']?1:0),iz=(KEYS['w']||KEYS['arrowup']?1:0)-(KEYS['s']||KEYS['arrowdown']?1:0);
    const dragged=MONV.zer&&MONV.zer.drag===myId();
    if((ix||iz)&&!dragged&&!uiOpen()){const fx=-Math.sin(P.yaw),fz=-Math.cos(P.yaw),rx=Math.cos(P.yaw),rz=-Math.sin(P.yaw);let mx=fx*iz+rx*ix,mz=fz*iz+rz*ix;const ml=Math.hypot(mx,mz)||1,sp=myLevel()>=12?1.4:0.8;
      P.x=clamp(P.x+mx/ml*sp*dt,-HALF+3,HALF-3);P.z=clamp(P.z+mz/ml*sp*dt,-HALF+3,HALF-3);P.fa=Math.atan2(mx,mz)}
    P.y=groundAt(P.x,P.z);me.g.position.set(P.x,P.y,P.z);me.g.rotation.y=P.fa;
  }else{fine.textContent='Waking up in the nurse\'s office…';if(MONV.zer&&MONV.zer.drag===myId())me.g.position.set(P.x,P.y,P.z)}
}

/* ---- pings (G) and proximity chat (Enter) ---- */
const PINGS=[],pingV=new T.Vector3();
function pingAt(x,z,who,color){
  const g=new T.Group();const beam=new T.Mesh(new T.CylinderGeometry(0.14,0.14,16,6,1,true),new T.MeshBasicMaterial({color,transparent:true,opacity:0.6,depthWrite:false,fog:false}));beam.position.y=8;
  const ring=new T.Mesh(new T.RingGeometry(0.5,0.85,18),new T.MeshBasicMaterial({color,side:T.DoubleSide,fog:false}));ring.rotation.x=-Math.PI/2;ring.position.y=0.15;g.add(beam,ring);
  g.position.set(x,groundAt(x,z),z);scene.add(g);const L=makeLabel(g,'','',2.6);say(L,who+': over here!',8000);PINGS.push({g,L,beam,x,z,t:8,color});
  tone(1320,0.12,'sine',0.08);setTimeout(()=>tone(1760,0.15,'sine',0.07),120);
}
function doPing(){
  camera.getWorldDirection(pingV);const o=camera.position;let hit=null;
  for(let s=1;s<160;s+=0.5){const x=o.x+pingV.x*s,y=o.y+pingV.y*s,z=o.z+pingV.z*s;if(y<=groundAt(x,z)){hit={x,z};break}}
  if(!hit){toast('Point at the ground to ping.','',1500);return}
  if(online())wsSend({t:'ping',x:hit.x,z:hit.z});else pingAt(hit.x,hit.z,'You',0xffd23a);
}
function updatePings(dt){for(let i=PINGS.length-1;i>=0;i--){const p=PINGS[i];p.t-=dt;p.beam.material.opacity=0.35+Math.abs(Math.sin(p.t*4))*0.35;if(p.t<=0){scene.remove(p.g);dropLabel(p.L);PINGS.splice(i,1)}}}
const chatIn=$('#chatIn');
function chatOpen(){return!chatIn.hidden}
function openChat(){chatIn.hidden=false;chatIn.value='';releaseLock();digHeld=false;for(const k in KEYS)KEYS[k]=false;setTimeout(()=>chatIn.focus(),10)}
function closeChat(){chatIn.hidden=true;chatIn.blur()}
function sendChat(){const s=chatIn.value.replace(/[\u0000-\u001f<>]/g,'').trim().slice(0,80);closeChat();if(!s)return;say(meL,s,6500);S.noise=1;wsSend({t:'chat',s});walkieChatSent()}

/* ---- flashlight (L): yours, plus the three nearest friends' ---- */
const FL=[];for(let i=0;i<4;i++){const s=new T.SpotLight(0xfff1d0,0,42,0.42,0.45,1.2);scene.add(s,s.target);FL.push(s)}
function toggleLight(){if(!S.light&&S.batt<=0){toast('Your flashlight battery is dead. The Supply Depot sells batteries.','bad',2500);return}S.light=!S.light;tone(S.light?1800:1200,0.05,'square',0.05)}
function aimLight(s,x,y,z,dx,dy,dz,on){s.intensity=on?tune('light.power'):0;if(!on)return;s.distance=tune('light.reach');s.angle=Math.min(1.4,tune('light.width'));s.penumbra=tune('light.soft');s.decay=tune('light.falloff');   // F2 > Flashlight
  s.position.set(x,y,z);s.target.position.set(x+dx*10,y+dy*10,z+dz*10);s.target.updateMatrixWorld()}
function updateLights(dt){
  if(S.light){S.batt=Math.max(0,S.batt-dt*tune('light.drain'));if(S.batt<=0){S.light=false;toast('Your flashlight died.','bad',2000)}}
  camera.getWorldDirection(pingV);
  const hy=P.y+(P.crouch?1:1.5);aimLight(FL[0],P.x+pingV.x*0.4,hy,P.z+pingV.z*0.4,pingV.x,pingV.y-0.05,pingV.z,S.light&&!S.ko);
  const lit=[...remotes.values()].filter(R=>R.f&4).map(R=>({R,d:(R.p.g.position.x-P.x)**2+(R.p.g.position.z-P.z)**2})).sort((a,b)=>a.d-b.d);
  for(let i=1;i<FL.length;i++){const e=lit[i-1];if(!e){aimLight(FL[i],0,0,0,0,0,0,false);continue}const g=e.R.p.g;const r=g.rotation.y;aimLight(FL[i],g.position.x,g.position.y+1.5,g.position.z,Math.sin(r),-0.15,Math.cos(r),true)}
}

/* ---- everything above, once a frame ---- */
let luckyT=0;
function updateCoop(dt){
  if(!S.started)return;
  if(clockT()<DAYMS)S.dayPlay=(S.dayPlay||0)+dt;
  S.noise=Math.max(0,S.noise-dt*0.35);if(P.anim===4)S.noise=Math.max(S.noise,0.6);
  // heavy loot (the server moves it when online)
  // heavy loot moves by grab physics now: 84-grab.js (updateGrab)
  // hold F next to a downed friend for 3 seconds to pick them up
  const dn=!S.ko&&!uiOpen()&&KEYS['f']?remoteNear(R=>R.f&2,2.4):null;
  if(dn){S.revT+=dt;const need=S.medkit>0?1:3;if(S.revT>=need){S.revT=0;if(need===1){S.medkit--;showSupply('medkit');toast('You used a first-aid kit.','',1800)}wsSend({t:'revive',id:dn.rid});addXP(50);countUp('helps',10,'ladder');toast(`You picked up ${dn.R.name}.`,'good',2500);sfx.find()}}else S.revT=0;
  // stuck in a deep hole: hold Space to climb out slowly (fast with a rope ladder)
  if(isTrapped()&&KEYS[' ']&&!uiOpen()){S.climbT+=dt;if(S.climbT>=(S.up.rope?1.5:8)){popOut();toast('You climbed out.','',1500)}}else if(!isTrapped())S.climbT=0;
  updatePings(dt);updateLights(dt);
  // Lucky Eye (level 8): dust puffs up over loot buried near you
  if(myLevel()>=8&&(luckyT-=dt)<=0){luckyT=1.3;let best=null,bd=36;for(const it of items){if(it.found||LOOT[it.type].key)continue;const d2=(it.x-P.x)**2+(it.z-P.z)**2;if(d2<bd){bd=d2;best=it}}if(best){const y=groundAt(best.x,best.z);puff(best.x,y+0.1,best.z,best.x,best.z,3)}}
}
